export const SKILLS: Record<string, { descricao: string; arquivos: Record<string, string> }> = {
  "prontidao-certificacao": {
    descricao: "Use ao avaliar se um SGSI/PIMS ISO 27001:2022 / 27701:2025 está pronto para Stage 1 e Stage 2 da certificadora, cruzando documento, registro na n.iso e prova operacional",
    arquivos: {
      "SKILL.md": "---\nname: prontidao-certificacao\ndescription: Use ao avaliar se um SGSI/PIMS ISO 27001:2022 / 27701:2025 está pronto para Stage 1 e Stage 2 da certificadora, cruzando documento, registro na n.iso e prova operacional\n---\n\n# Pré-avaliação de prontidão para certificação (ISO/IEC 27001:2022 + ISO/IEC 27701:2025)\n\n## Papel\n\n- Você é avaliador com o critério de uma certificadora: pergunta o que o auditor do organismo de certificação perguntaria e só aceita o que ele aceitaria.\n- O trabalho é **pré-avaliação de prontidão da consultoria**. Não é auditoria interna (ISO/IEC 27001, 9.2): quem implementou o sistema não o avalia como auditor interno, e o resultado não substitui o programa de auditoria interna da organização.\n- Nenhum achado é gravado na n.iso. Leitura apenas (`niso_ler`, `niso_coherence_check`, `niso_gap_analysis`, `niso_traceability`). Nenhuma escrita em repositório remoto. Não use `niso_executar` nesta avaliação.\n- Esta skill chega pelo MCP: `niso_skill` sem argumentos lista o que existe; `niso_skill` com `nome` traz este arquivo; com `arquivo` traz uma referência ou o validador (ex.: `arquivo=references/armadilhas-certificadora.md`).\n\n## Fontes\n\nTodo requisito é cruzado em três fontes, todas somente leitura:\n\n1. **Documento** — a informação documentada do SGSI/PIMS na pasta de trabalho (políticas, procedimentos, SoA, registro de fatos canônicos).\n2. **Registro** — o snapshot da n.iso, montado por você no início (ver \"Como montar o snapshot\"): controles, evidências (lista e conteúdo), riscos, ativos, políticas, auditorias, análises críticas, CAPA, treinamentos, fornecedores, governança, ROPA, DPIA, coherence check e gap analysis.\n3. **Prova operacional** — só o que já existe nos insumos locais e na n.iso. O agente não acessa o ambiente de nuvem do cliente: prova que o consultor não trouxe vira achado e gera um item em `export_pedido` (comando só-leitura, ver `references/anexo-a-27001.md`; os exemplos são AWS e GitHub, adapte ao que o cliente usa).\n\nSe uma rota do snapshot falhou (erro, 404), trate como \"sem registro no snapshot\", nunca como \"não existe\"; o erro está em `_snapshot/_erros.md`.\n\n## Como montar o snapshot\n\nAntes de avaliar, leia o registro com `niso_ler` (o mapa de caminhos está em `niso_contexto`; `{p}` = projectId) e grave cada resposta como arquivo em `_snapshot/` na pasta de trabalho:\n\n- controles `/api/v1/projects/{p}/controls`; riscos `/api/v1/projects/{p}/risks`; ativos `/api/v1/projects/{p}/assets`\n- evidências `/api/v1/projects/{p}/evidence` e, para cada uma de texto, `/api/v1/evidence/{id}/content` (binário volta só como metadado: registre como \"conteúdo não lido\")\n- políticas e versões `/api/v1/projects/{p}/controls/{controle}/versions`\n- auditorias `/api/v1/projects/{p}/audits`; análises críticas `/api/v1/projects/{p}/management-reviews`; CAPA `/api/v1/projects/{p}/capa`\n- treinamento `/training`, fornecedores `/vendors`, governança `/governance`, ROPA `/ropa`, DPIA `/dpia` (todos sob `/api/v1/projects/{p}/`)\n- diagnóstico: `niso_coherence_check`, `niso_gap_analysis`, `niso_traceability`\n\nAnote em `_snapshot/_erros.md` toda rota que falhou e liste em `_snapshot/ids.txt` os ids que aparecem (um por linha); é o arquivo que o validador usa em `--fontes`. Respostas grandes vêm cortadas em 100.000 caracteres: nesse caso peça por item e registre o corte.\n\n## Regra de fechamento\n\n- Um item só é `atende` quando **documento, registro e prova** fecham entre si.\n- Duas de três = `parcial`. Nenhuma ou só documento sem aprovação = `nao_atende`.\n- Achado sem `fonte` (caminho relativo à raiz de trabalho ou id da n.iso: `ctrl-…`, `audit-…`, id de evidência etc.) é **descartado**.\n- Não inventar evidência, data, pessoa, valor ou número de controle. Na dúvida, registre a dúvida como achado ou pergunta, não como fato.\n\n## Severidade\n\n| Severidade | Quando usar |\n|---|---|\n| `NC maior` | Requisito obrigatório (\"deve\") da norma ausente; **ou** falha que se repete em 3 ou mais itens do mesmo requisito (falha sistêmica); **ou** ausência total de registro de uma cláusula 9 ou 10 (monitoramento, auditoria interna, análise crítica, não conformidade/ação corretiva, melhoria). Impede a recomendação para certificação. |\n| `NC menor` | Falha pontual ou isolada no atendimento de um requisito; o requisito existe e funciona na maior parte. |\n| `OM` | Oportunidade de melhoria: nenhum requisito violado. Boa prática, clareza, eficiência. |\n\nNC maior precisa de fundamento normativo (cláusula ou controle citado em `requisito`). \"Boa prática\" sozinha nunca sustenta NC maior; rebaixe para NC menor ou OM.\n\n## Vereditos S1/S2\n\n- **`veredito_s1` (Stage 1, documental)** — o documento existe; está aprovado, com data e aprovador de papel válido; é coerente com a SoA e com o registro na n.iso.\n- **`veredito_s2` (Stage 2, operação)** — há registro de operação no período avaliado, verificável por amostra (ex.: 3 a 5 ocorrências: tickets, logs, atas, exports).\n- Valores: `atende` | `parcial` | `nao_atende` | `na` (use `na` apenas quando o requisito não se aplica ao stage, com a razão na constatação).\n\n## Formato do achado\n\nUma linha por achado em `bloco-N.csv`, separador `;`, codificação `utf-8-sig`, cabeçalho exato:\n\n```\nid;bloco;requisito;severidade;veredito_s1;veredito_s2;pergunta_auditor;constatacao;fonte;correcao;dono;export_pedido\n```\n\n- `id`: `B<bloco>-<nn>` (ex.: `B3-07`), único no arquivo.\n- `requisito`: cláusula ou controle (ex.: `9.3.2`, `A.8.15`, `27701 A.1.x (a confirmar)`).\n- `pergunta_auditor`: a pergunta que o auditor faria.\n- `constatacao`: o que foi observado, factual, sem adjetivo.\n- `fonte`: obrigatória; várias fontes separadas por `|`.\n- `correcao`: ação concreta que fecha o achado.\n- `dono`: um papel, nunca nome de pessoa (ex.: CEO, COO, CIO / Líder de Operações de Segurança, CTO, DevOps Lead, Encarregado (parecer), consultoria). Use os papéis da governança do projeto (`/api/v1/projects/{p}/governance`) ou a lista que o consultor fixou para a rodada.\n- `export_pedido`: comando só-leitura ou artefato pedido quando falta prova; vazio se não houver.\n- Campos obrigatórios: todos, exceto `pergunta_auditor` e `export_pedido`.\n\nConsultar: `references/clausulas-27001.md`, `references/clausulas-27701.md`, `references/anexo-a-27001.md`, `references/anexo-a-27701.md`, `references/armadilhas-certificadora.md`.\n\n## Proibições\n\n- Não gravar nada na n.iso nem em repositório remoto.\n- Não chamar o próprio trabalho de \"auditoria\", nem usar \"auditado\" ou \"conforme\" para descrevê-lo. Use \"pré-avaliação\", \"avaliado\", \"atende\".\n- Não usar \"100%\" nem termos vedados para este cliente (o validador reprova; o consultor informa a lista e você a passa em `--proibidos`).\n- Não inventar evidência, data, pessoa, valor ou numeração normativa.\n- Não citar contexto fora do escopo definido para o SGSI/PIMS avaliado (nenhum cliente, parceiro ou projeto externo nomeado).\n- Não copiar texto normativo das ISO: parafrasear.\n- Numeração das Tabelas A.1/A.2/A.3 da ISO/IEC 27701:2025: tratar como item a confirmar contra o texto oficial.\n\n## Como validar\n\nO validador é um arquivo desta skill: traga com `niso_skill` (`arquivo=scripts/check_achados.py`), grave na pasta de trabalho e rode com Python 3.\n\n```\npython check_achados.py bloco-N.csv\npython check_achados.py bloco-N.csv --fontes <raiz de trabalho> _snapshot/ids.txt\npython check_achados.py bloco-N.csv --proibidos \"termo1,termo2\"\npython check_achados.py --selftest\n```\n\nSaída `OK <n> achados` (exit 0) ou uma linha `ERRO linha <n>: <motivo>` por problema (exit 1). Com `--fontes`, cada fonte precisa existir como arquivo sob a raiz ou constar em `snapshot_ids.txt`. Corrija até passar antes de entregar o bloco.\n",
      "references/anexo-a-27001.md": "# ISO/IEC 27001:2022 — Anexo A (93 controles, paráfrase)\n\nNomes em português por paráfrase; não substitui o texto oficial. Comandos da última coluna são **só leitura**; `<...>` indica parâmetro a preencher; `{owner}/{repo}` e `{org}` são do GitHub. \"—\" = sem export técnico típico (a prova é documental ou de registro). Controles físicos (A.7) em infraestrutura de nuvem são em grande parte herdados do provedor: a prova é o relatório de terceira parte do provedor mais o controle dos locais próprios (escritório, trabalho remoto).\n\n| Controle | Nome | S1 (documento esperado) | S2 (registro/prova esperada) | Export típico AWS/GitHub |\n|---|---|---|---|---|\n| A.5.1 | Políticas de segurança da informação | Política geral e políticas temáticas aprovadas, com data e aprovador | Comunicação e aceite; revisão no intervalo planejado | — |\n| A.5.2 | Papéis e responsabilidades de segurança da informação | Matriz de papéis e responsabilidades | Nomeações formais; papéis exercidos nos registros | — |\n| A.5.3 | Segregação de funções | Regra de segregação (quem solicita, aprova, executa) | Amostra de mudanças com autor diferente do aprovador | `gh api repos/{owner}/{repo}/branches/main/protection` |\n| A.5.4 | Responsabilidades da direção | Política exige que gestores cobrem a aplicação da SI | Evidência de cobrança/acompanhamento pela direção | — |\n| A.5.5 | Contato com autoridades | Lista de autoridades e quando acioná-las (incl. autoridade de proteção de dados) | Registro de contatos ou teste da lista | — |\n| A.5.6 | Contato com grupos de interesse especial | Lista de grupos, fóruns e fontes | Participação ou assinatura ativa | — |\n| A.5.7 | Inteligência de ameaças | Procedimento de coleta e análise de inteligência de ameaças | Registros de análise e ação derivada | `aws guardduty list-detectors` |\n| A.5.8 | Segurança da informação no gerenciamento de projetos | Requisito de SI no ciclo de projetos | Projetos com análise de SI registrada | `gh issue list --label security --state all --limit 50` |\n| A.5.9 | Inventário de informações e outros ativos associados | Inventário com dono | Inventário atualizado e coerente com o ambiente | `aws resourcegroupstaggingapi get-resources --region sa-east-1` |\n| A.5.10 | Uso aceitável de informações e outros ativos | Política de uso aceitável | Aceite registrado por colaborador | — |\n| A.5.11 | Devolução de ativos | Procedimento de devolução no desligamento | Checklists de desligamento assinados | — |\n| A.5.12 | Classificação da informação | Esquema de classificação | Ativos classificados no inventário | `aws resourcegroupstaggingapi get-resources --tag-filters Key=<chave_classificacao>` |\n| A.5.13 | Rotulagem de informações | Procedimento de rotulagem coerente com a classificação | Amostra de ativos/documentos rotulados | `aws resourcegroupstaggingapi get-resources --tag-filters Key=<chave_classificacao>` |\n| A.5.14 | Transferência de informações | Regras de transferência (canais, acordos, cifragem) | Evidência de transferência protegida | `aws elbv2 describe-listeners --load-balancer-arn <arn>` |\n| A.5.15 | Controle de acesso | Política de controle de acesso (necessidade de saber, menor privilégio) | Acessos concedidos seguem a política | `aws iam get-account-authorization-details` |\n| A.5.16 | Gestão de identidade | Ciclo de vida de identidades | Identidades únicas; contas órfãs inexistentes | `aws iam list-users` |\n| A.5.17 | Informações de autenticação | Regras de senha, MFA e gestão de segredos | Política de senha aplicada; segredos em cofre | `aws iam get-account-password-policy` |\n| A.5.18 | Direitos de acesso | Procedimento de concessão, revisão e revogação | Revisões periódicas de acesso registradas | `aws iam get-credential-report` (após `generate-credential-report`) |\n| A.5.19 | Segurança da informação nas relações com fornecedores | Política de fornecedores com critérios de SI | Avaliação de SI por fornecedor crítico | `aws artifact list-reports` |\n| A.5.20 | Segurança da informação nos contratos com fornecedores | Cláusulas-padrão de SI e proteção de dados | Contratos vigentes com as cláusulas | — |\n| A.5.21 | Gestão da SI na cadeia de suprimentos de TIC | Requisitos para componentes e software de terceiros | Inventário de dependências e sua avaliação | `gh api repos/{owner}/{repo}/dependency-graph/sbom` |\n| A.5.22 | Monitoramento, análise crítica e gestão de mudanças dos serviços de fornecedores | Procedimento de acompanhamento de fornecedores | Revisões periódicas; avisos de mudança tratados | `aws health describe-events` |\n| A.5.23 | Segurança da informação no uso de serviços em nuvem | Política de uso de nuvem (aquisição, uso, gestão, saída) | Responsabilidade compartilhada mapeada; configuração da conta | `aws organizations describe-organization` |\n| A.5.24 | Planejamento e preparação da gestão de incidentes | Plano de resposta a incidentes com papéis | Plano testado (simulado) | — |\n| A.5.25 | Avaliação e decisão sobre eventos de SI | Critérios de classificação de eventos | Eventos triados com decisão registrada | `aws securityhub get-findings --max-items 50` |\n| A.5.26 | Resposta a incidentes de SI | Procedimento de resposta | Registros de incidentes tratados | `aws guardduty list-findings --detector-id <id>` |\n| A.5.27 | Aprendizado com incidentes | Etapa de lições aprendidas no procedimento | Relatórios pós-incidente com ação | — |\n| A.5.28 | Coleta de evidências | Procedimento de coleta e preservação | Integridade de logs preservada | `aws cloudtrail describe-trails` |\n| A.5.29 | Segurança da informação durante disrupção | Plano de continuidade com requisitos de SI | Teste do plano | `aws backup list-backup-plans` |\n| A.5.30 | Prontidão de TIC para continuidade de negócios | RTO/RPO definidos para os serviços de TIC | Teste de restauração dentro do RTO/RPO | `aws backup list-restore-jobs` |\n| A.5.31 | Requisitos legais, estatutários, regulamentares e contratuais | Registro de requisitos aplicáveis | Registro atualizado; monitoramento de mudanças | — |\n| A.5.32 | Direitos de propriedade intelectual | Regras de licenciamento e uso de software | Inventário de licenças | `gh api repos/{owner}/{repo}/license` |\n| A.5.33 | Proteção de registros | Tabela de retenção e proteção de registros | Retenção aplicada nos sistemas | `aws logs describe-log-groups` |\n| A.5.34 | Privacidade e proteção de dados pessoais | Política de privacidade; ROPA | Tratamentos registrados; direitos do titular atendidos | `aws macie2 list-findings` |\n| A.5.35 | Análise crítica independente da segurança da informação | Previsão de revisão independente | Relatório de revisão independente | — |\n| A.5.36 | Conformidade com políticas, regras e normas de SI | Procedimento de verificação de conformidade | Verificações periódicas registradas | `aws configservice describe-compliance-by-config-rule` |\n| A.5.37 | Procedimentos operacionais documentados | Procedimentos/runbooks das operações críticas | Procedimentos disponíveis e usados | — |\n| A.6.1 | Seleção | Regra de verificação de antecedentes proporcional ao risco | Verificações registradas por contratado | — |\n| A.6.2 | Termos e condições de contratação | Contratos com responsabilidades de SI | Contratos assinados | — |\n| A.6.3 | Conscientização, educação e treinamento em SI | Programa de conscientização e reciclagem | Registros de treinamento no período | — |\n| A.6.4 | Processo disciplinar | Processo disciplinar formal comunicado | Comunicação do processo | — |\n| A.6.5 | Responsabilidades após encerramento ou mudança de vínculo | Obrigações pós-vínculo | Desligamentos com acessos revogados no prazo | `gh api orgs/{org}/members --paginate` |\n| A.6.6 | Acordos de confidencialidade | Modelo de acordo de confidencialidade | Acordos assinados e revisados | — |\n| A.6.7 | Trabalho remoto | Política de trabalho remoto | Aceite e controles aplicados | — |\n| A.6.8 | Relato de eventos de SI | Canal e instrução de relato | Eventos relatados pelo canal | — |\n| A.7.1 | Perímetros de segurança física | Definição dos perímetros próprios; herança do provedor | Relatório de terceira parte do provedor | `aws artifact list-reports` |\n| A.7.2 | Entrada física | Controle de acesso físico aos locais próprios | Registros de acesso | — |\n| A.7.3 | Segurança de escritórios, salas e instalações | Requisitos de proteção dos locais próprios | Inspeção ou evidência | — |\n| A.7.4 | Monitoramento da segurança física | Monitoramento dos locais próprios; herança do provedor | Relatório de terceira parte do provedor | `aws artifact list-reports` |\n| A.7.5 | Proteção contra ameaças físicas e ambientais | Avaliação de ameaças físicas; herança do provedor | Relatório de terceira parte do provedor | `aws artifact list-reports` |\n| A.7.6 | Trabalho em áreas seguras | Regras para áreas seguras (se existirem) | Evidência de aplicação | — |\n| A.7.7 | Mesa limpa e tela limpa | Regra de mesa e tela limpas | Bloqueio automático de tela configurado | — |\n| A.7.8 | Localização e proteção de equipamentos | Regras para equipamentos próprios | Evidência de aplicação | — |\n| A.7.9 | Segurança de ativos fora das instalações | Regras para equipamentos fora do escritório | Equipamentos cifrados e inventariados | — |\n| A.7.10 | Mídias de armazenamento | Gestão, transporte e descarte de mídias | Cifragem de volumes; registros de descarte | `aws ec2 get-ebs-encryption-by-default` |\n| A.7.11 | Utilidades de suporte | Requisitos de energia e utilidades; herança do provedor | Relatório de terceira parte do provedor | `aws artifact list-reports` |\n| A.7.12 | Segurança do cabeamento | Requisitos para cabeamento próprio; herança do provedor | Relatório de terceira parte do provedor | `aws artifact list-reports` |\n| A.7.13 | Manutenção de equipamentos | Regra de manutenção dos equipamentos próprios | Registros de manutenção | — |\n| A.7.14 | Descarte seguro ou reutilização de equipamentos | Procedimento de descarte com apagamento | Registros de descarte; herança do provedor para mídia em nuvem | `aws artifact list-reports` |\n| A.8.1 | Dispositivos de endpoint do usuário | Política de endpoints (cifragem, atualização, bloqueio) | Inventário e estado dos endpoints | — |\n| A.8.2 | Direitos de acesso privilegiado | Regra de concessão e revisão de acesso privilegiado | Lista de privilegiados revisada | `aws iam list-entities-for-policy --policy-arn arn:aws:iam::aws:policy/AdministratorAccess` |\n| A.8.3 | Restrição de acesso à informação | Regras de restrição por política de acesso | Recursos sem acesso público indevido | `aws s3api get-public-access-block --bucket <bucket>` |\n| A.8.4 | Acesso ao código-fonte | Regra de acesso ao código | Colaboradores e permissões revisados | `gh api repos/{owner}/{repo}/collaborators --paginate` |\n| A.8.5 | Autenticação segura | Exigência de MFA e autenticação forte | MFA ativo em todas as contas | `gh api \"orgs/{org}/members?filter=2fa_disabled\"` |\n| A.8.6 | Gestão de capacidade | Monitoramento e projeção de capacidade | Alarmes e revisões de capacidade | `aws cloudwatch describe-alarms` |\n| A.8.7 | Proteção contra malware | Política antimalware | Detecção ativa e alertas tratados | `aws guardduty get-detector --detector-id <id>` |\n| A.8.8 | Gestão de vulnerabilidades técnicas | Procedimento com prazos por severidade | Vulnerabilidades tratadas no prazo | `aws inspector2 list-findings` |\n| A.8.9 | Gestão de configuração | Linhas de base de configuração | Desvios detectados e tratados | `aws configservice describe-configuration-recorders` |\n| A.8.10 | Exclusão de informações | Regra de exclusão ao fim da retenção | Exclusões executadas | `aws s3api get-bucket-lifecycle-configuration --bucket <bucket>` |\n| A.8.11 | Mascaramento de dados | Regra de mascaramento/pseudonimização | Dados mascarados em logs e não produção | `aws logs get-data-protection-policy --log-group-identifier <log_group>` |\n| A.8.12 | Prevenção de vazamento de dados | Medidas de prevenção de vazamento | Alertas de exposição tratados | `gh api repos/{owner}/{repo}/secret-scanning/alerts` |\n| A.8.13 | Backup de informações | Política de backup (escopo, frequência, retenção, teste) | Jobs concluídos e teste de restauração | `aws backup list-backup-jobs --by-state COMPLETED` |\n| A.8.14 | Redundância dos recursos de tratamento | Requisitos de disponibilidade e redundância | Recursos em múltiplas zonas | `aws rds describe-db-instances` |\n| A.8.15 | Registro de logs | Política de logs (o quê, retenção, proteção) | Trilhas ativas e íntegras; retenção aplicada | `aws cloudtrail get-trail-status --name <trail>` |\n| A.8.16 | Atividades de monitoramento | Procedimento de monitoramento de comportamento anômalo | Alertas gerados e tratados | `aws guardduty list-findings --detector-id <id>` |\n| A.8.17 | Sincronização de relógio | Fonte de tempo definida | Sistemas sincronizados | — |\n| A.8.18 | Uso de programas utilitários privilegiados | Restrição de utilitários privilegiados | Sessões privilegiadas registradas | `aws ssm describe-sessions --state History` |\n| A.8.19 | Instalação de software em sistemas operacionais | Regra de instalação de software | Inventário de software instalado | `aws ssm list-inventory-entries --instance-id <id> --type-name AWS:Application` |\n| A.8.20 | Segurança de redes | Arquitetura e regras de rede | Regras de firewall revisadas | `aws ec2 describe-security-groups` |\n| A.8.21 | Segurança dos serviços de rede | Requisitos dos serviços de rede (TLS, WAF) | Serviços configurados de acordo com os requisitos | `aws wafv2 list-web-acls --scope REGIONAL` |\n| A.8.22 | Segregação de redes | Segmentação definida | Sub-redes e rotas coerentes com o desenho | `aws ec2 describe-subnets` |\n| A.8.23 | Filtragem da web | Regra de filtragem de acesso externo | Filtros aplicados | `aws route53resolver list-firewall-rule-group-associations` |\n| A.8.24 | Uso de criptografia | Política de criptografia e gestão de chaves | Cifragem em repouso e trânsito; rotação de chaves | `aws kms get-key-rotation-status --key-id <id>` |\n| A.8.25 | Ciclo de vida de desenvolvimento seguro | Regras de desenvolvimento seguro | Esteira com controles de segurança | `gh run list --limit 20` |\n| A.8.26 | Requisitos de segurança de aplicações | Requisitos de segurança definidos por aplicação | Requisitos rastreados até a entrega | — |\n| A.8.27 | Arquitetura e engenharia de sistemas seguros | Princípios de arquitetura segura | Aplicação dos princípios em desenhos | — |\n| A.8.28 | Codificação segura | Padrão de codificação segura | Análise estática ativa e alertas tratados | `gh api repos/{owner}/{repo}/code-scanning/alerts` |\n| A.8.29 | Testes de segurança em desenvolvimento e aceitação | Plano de testes de segurança | Resultados de testes e pentest | `gh run list --workflow <workflow> --limit 20` |\n| A.8.30 | Desenvolvimento terceirizado | Requisitos para desenvolvimento externo | Supervisão registrada (ou exclusão justificada) | — |\n| A.8.31 | Separação dos ambientes de desenvolvimento, teste e produção | Regra de separação | Ambientes em contas ou redes separadas | `aws organizations list-accounts` |\n| A.8.32 | Gestão de mudanças | Procedimento de mudanças | Mudanças com revisão e aprovação | `gh pr list --state merged --limit 50 --json number,title,reviewDecision,mergedAt` |\n| A.8.33 | Informações de teste | Regra de uso de dados em teste | Ausência de dado pessoal real em teste | — |\n| A.8.34 | Proteção de sistemas durante testes de auditoria | Regra para testes de verificação em produção | Testes planejados e autorizados | — |\n",
      "references/anexo-a-27701.md": "# ISO/IEC 27701:2025 — Anexo A (paráfrase) com correspondência LGPD\n\n> **Numeração a confirmar contra o texto oficial da 27701:2025.** A edição 2025 reorganizou os controles de privacidade em Tabela A.1 (controlador), Tabela A.2 (operador) e Tabela A.3 (segurança da informação para controladores e operadores). Os números abaixo **não** são citáveis sem conferência: a coluna \"Controle\" usa `A.1.x (a confirmar)` e traz a correspondência com a edição 2019 (`2019: A.7.x.y`), que serve apenas para localizar o tema. Em achado, cite `27701 A.1 (a confirmar) — <tema>`.\n\n## Tabela A.1 — Controles para controladores\n\n| Controle | Nome | S1 (documento esperado) | S2 (registro/prova esperada) | LGPD |\n|---|---|---|---|---|\n| A.1.x (a confirmar) — 2019: A.7.2.1 | Identificar e documentar a finalidade | Finalidades descritas por tratamento no ROPA | Tratamento real coerente com a finalidade declarada | Art. 6º, I; art. 9º |\n| A.1.x (a confirmar) — 2019: A.7.2.2 | Identificar a base legal | Base legal por tratamento; base específica para dado sensível | Base legal aplicada e comprovável (ex.: registro de consentimento) | Arts. 7º e 11 |\n| A.1.x (a confirmar) — 2019: A.7.2.3 | Determinar quando e como obter consentimento | Regra de quando o consentimento é a base e como é coletado | Fluxo de coleta implantado | Art. 8º; art. 11, I |\n| A.1.x (a confirmar) — 2019: A.7.2.4 | Obter e registrar consentimento | Modelo de termo; requisitos de registro | Registros de consentimento por titular, com data e versão do termo | Art. 8º, §§ 1º e 2º |\n| A.1.x (a confirmar) — 2019: A.7.2.5 | Avaliação de impacto à privacidade | Metodologia de RIPD/DPIA e critério de quando fazer | RIPD/DPIA concluído para tratamentos de alto risco (ex.: dado sensível) | Art. 38; art. 5º, XVII |\n| A.1.x (a confirmar) — 2019: A.7.2.6 | Contratos com operadores | Cláusulas-padrão de proteção de dados para operadores | Contratos vigentes com as cláusulas | Art. 39 |\n| A.1.x (a confirmar) — 2019: A.7.2.7 | Controlador conjunto | Acordo de responsabilidades quando houver controle conjunto | Acordo assinado (ou registro de que não se aplica) | Art. 42 |\n| A.1.x (a confirmar) — 2019: A.7.2.8 | Registros relacionados ao tratamento | ROPA com os elementos mínimos | ROPA atualizado e revisado no período | Art. 37 |\n| A.1.x (a confirmar) — 2019: A.7.3.1 | Determinar e cumprir obrigações com os titulares | Procedimento de atendimento aos direitos | Solicitações atendidas | Art. 18 |\n| A.1.x (a confirmar) — 2019: A.7.3.2 | Determinar informações para os titulares | Conteúdo mínimo do aviso de privacidade | Aviso publicado e coerente com o ROPA | Art. 9º |\n| A.1.x (a confirmar) — 2019: A.7.3.3 | Fornecer informações aos titulares | Canal e forma de disponibilizar as informações | Aviso acessível no ponto de coleta | Art. 9º; art. 18 |\n| A.1.x (a confirmar) — 2019: A.7.3.4 | Mecanismo para modificar ou retirar consentimento | Procedimento de revogação | Revogações processadas | Art. 8º, § 5º; art. 18, IX |\n| A.1.x (a confirmar) — 2019: A.7.3.5 | Mecanismo para oposição ao tratamento | Procedimento de oposição | Oposições processadas | Art. 18, § 2º |\n| A.1.x (a confirmar) — 2019: A.7.3.6 | Acesso, correção e/ou eliminação | Procedimento para cada direito | Solicitações atendidas no prazo | Art. 18, II, III e VI |\n| A.1.x (a confirmar) — 2019: A.7.3.7 | Obrigação de informar terceiros | Regra de comunicar correção/eliminação a quem recebeu os dados | Comunicações registradas | Art. 18, § 6º |\n| A.1.x (a confirmar) — 2019: A.7.3.8 | Fornecer cópia dos dados tratados | Formato e prazo da cópia | Cópias fornecidas | Art. 19 |\n| A.1.x (a confirmar) — 2019: A.7.3.9 | Tratamento de solicitações | Prazos e verificação de identidade do solicitante | Registro de solicitações com prazos | Art. 18, §§ 3º a 5º; art. 19 |\n| A.1.x (a confirmar) — 2019: A.7.3.10 | Decisões automatizadas | Identificação de decisões automatizadas e direito de revisão | Pedidos de revisão atendidos; critérios informados | Art. 20 |\n| A.1.x (a confirmar) — 2019: A.7.4.1 | Limitar a coleta | Dados coletados restritos ao necessário | Campos coletados coerentes com o ROPA | Art. 6º, III |\n| A.1.x (a confirmar) — 2019: A.7.4.2 | Limitar o tratamento | Tratamento restrito à finalidade | Ausência de uso secundário não previsto | Art. 6º, I a III |\n| A.1.x (a confirmar) — 2019: A.7.4.3 | Exatidão e qualidade | Regra de qualidade e atualização | Mecanismo de correção operando | Art. 6º, V |\n| A.1.x (a confirmar) — 2019: A.7.4.4 | Objetivos de minimização | Objetivos de minimização definidos | Medição ou verificação da minimização | Art. 6º, III |\n| A.1.x (a confirmar) — 2019: A.7.4.5 | Desidentificação e exclusão ao fim do tratamento | Regra de exclusão/anonimização ao fim da finalidade | Exclusões executadas | Arts. 15 e 16 |\n| A.1.x (a confirmar) — 2019: A.7.4.6 | Arquivos temporários | Regra de eliminação de temporários | Temporários eliminados no prazo | Art. 6º, III; art. 46 |\n| A.1.x (a confirmar) — 2019: A.7.4.7 | Retenção | Prazos de retenção por categoria de dado | Retenção aplicada nos sistemas | Arts. 15 e 16 |\n| A.1.x (a confirmar) — 2019: A.7.4.8 | Descarte | Procedimento de descarte seguro | Registros de descarte | Art. 16 |\n| A.1.x (a confirmar) — 2019: A.7.4.9 | Controles de transmissão | Proteção dos dados em transmissão | Cifragem em trânsito comprovada | Art. 46 |\n| A.1.x (a confirmar) — 2019: A.7.5.1 | Base para transferência internacional | Mecanismo de transferência por destino | Transferências amparadas no mecanismo | Art. 33; Res. CD/ANPD 19/2024 |\n| A.1.x (a confirmar) — 2019: A.7.5.2 | Países e organizações de destino | Lista de destinos informada ao titular | Lista coerente com fornecedores e regiões usadas | Art. 33; art. 9º |\n| A.1.x (a confirmar) — 2019: A.7.5.3 | Registros de transferência | Regra de registrar transferências | Registros de transferência | Art. 37 |\n| A.1.x (a confirmar) — 2019: A.7.5.4 | Registros de divulgação a terceiros | Regra de registrar compartilhamentos | Registros de compartilhamento | Art. 37; art. 18, VII |\n\n## Tabela A.2 — Controles para operadores\n\nNão tabelada aqui. Quando a organização atua **apenas como controladora** no escopo, a Tabela A.2 entra na SoA como **exclusão justificada** (papel declarado em 4.1 e no ROPA). Verificar: (a) a justificativa está escrita na SoA; (b) nenhum tratamento do ROPA declara a organização como operadora; (c) contratos não a qualificam como operadora. Se qualquer tratamento for de operador, a exclusão cai e a Tabela A.2 passa a ser avaliada (LGPD art. 39).\n\n## Tabela A.3 — Segurança da informação para controladores e operadores\n\nControles de segurança com extensão de privacidade. A coluna \"Controle\" referencia o controle da 27001 que o item estende; o número próprio na Tabela A.3 fica **(a confirmar)**.\n\n| Controle | Nome | S1 (documento esperado) | S2 (registro/prova esperada) | LGPD |\n|---|---|---|---|---|\n| A.3.x (a confirmar) — 27001 A.5.2 | Papéis de privacidade | Encarregado nomeado; responsabilidade de privacidade na matriz | Nomeação e canal do encarregado publicados | Art. 41 |\n| A.3.x (a confirmar) — 27001 A.5.12 | Classificação incluindo dado pessoal e sensível | Esquema de classificação com categorias de dado pessoal | Ativos com dado pessoal/sensível identificados | Art. 5º, I e II |\n| A.3.x (a confirmar) — 27001 A.5.15 | Controle de acesso a dado pessoal | Regra de menor privilégio para dado pessoal | Revisão de acesso a sistemas com dado pessoal | Art. 46; art. 47 |\n| A.3.x (a confirmar) — 27001 A.5.19/A.5.20 | Fornecedores e operadores | Cláusulas de proteção de dados e de suboperação | Contratos e avaliações de fornecedores | Art. 39; art. 42 |\n| A.3.x (a confirmar) — 27001 A.5.24–A.5.26 | Incidentes envolvendo dado pessoal | Procedimento com avaliação de risco ao titular e comunicação à autoridade e aos titulares | Registro de incidentes, inclusive os não comunicados, com a avaliação | Art. 48; Res. CD/ANPD 15/2024 |\n| A.3.x (a confirmar) — 27001 A.5.31 | Requisitos legais de privacidade | Registro de LGPD e regulamentação da autoridade | Registro atualizado | Arts. 6º e 50 |\n| A.3.x (a confirmar) — 27001 A.5.33 | Proteção e retenção de registros | Retenção de registros de tratamento e de incidentes | Registros preservados pelo prazo | Art. 37; Res. CD/ANPD 15/2024 |\n| A.3.x (a confirmar) — 27001 A.5.34 | Privacidade e proteção de dados pessoais | Política de privacidade; ROPA; RIPD | Tratamentos registrados e direitos atendidos | Arts. 37, 38 e 50 |\n| A.3.x (a confirmar) — 27001 A.6.3 | Treinamento em privacidade | Conteúdo de privacidade no programa de conscientização | Registros de treinamento de quem trata dado pessoal | Art. 50, § 2º |\n| A.3.x (a confirmar) — 27001 A.6.6 | Confidencialidade de quem trata dado pessoal | Acordo de confidencialidade cobrindo dado pessoal | Acordos assinados | Art. 47 |\n| A.3.x (a confirmar) — 27001 A.8.10 | Exclusão de dado pessoal | Regra de exclusão ao fim da finalidade | Exclusões executadas | Arts. 15 e 16 |\n| A.3.x (a confirmar) — 27001 A.8.11 | Mascaramento e pseudonimização | Regra de mascaramento em logs e ambientes | Logs sem dado pessoal em claro | Art. 13, § 4º; art. 46 |\n| A.3.x (a confirmar) — 27001 A.8.13 | Backup com dado pessoal | Retenção e exclusão também em backups | Backups respeitam retenção e cifragem | Arts. 16 e 46 |\n| A.3.x (a confirmar) — 27001 A.8.15 | Logs de acesso a dado pessoal | Regra de registrar acesso a dado pessoal | Logs ativos, protegidos e retidos | Art. 37; art. 46 |\n| A.3.x (a confirmar) — 27001 A.8.24 | Criptografia de dado pessoal | Cifragem em repouso e trânsito para dado pessoal/sensível | Cifragem comprovada; gestão de chaves | Art. 46 |\n| A.3.x (a confirmar) — 27001 A.8.33 | Dado pessoal em teste | Proibição de dado pessoal real em teste ou regra de anonimização | Ambientes de teste sem dado real | Art. 6º, III; art. 46 |\n",
      "references/armadilhas-certificadora.md": "# Armadilhas recorrentes na certificação\n\nAchados que o auditor da certificadora costuma encontrar. Severidade típica é ponto de partida: aplicar o critério de `SKILL.md` (≥3 itens do mesmo requisito = sistêmico = NC maior).\n\n| # | Armadilha | Sintoma | Como verificar | Severidade típica |\n|---|---|---|---|---|\n| 1 | SoA × ferramenta divergentes | Controle \"Sim\" na SoA e \"Não Aplicável\" na n.iso (ou o inverso); estado de implementação diferente | Comparar a SoA local com os controles do snapshot, **um a um, sem amostragem** | NC menor por item; NC maior se ≥3 divergências (6.1.3 d) |\n| 2 | Risco sem vínculo a controle | Risco tratado por \"mitigar\" sem controle associado, ou controle na SoA sem risco que o justifique | Rastrear risco → controle → documento → evidência (`niso_traceability`) | NC menor; NC maior se sistêmico (6.1.3, 8.3) |\n| 3 | Aprovação sem data ou por papel indevido | Documento sem data de aprovação, aprovado por quem o redigiu ou por papel sem autoridade | Conferir cabeçalho/controle de versão de cada documento e o aprovador contra a matriz de papéis (5.3) | NC menor; NC maior se a política (5.2) ou a SoA estiver nessa situação |\n| 4 | Controle \"Implementado\" sem registro | Estado \"Implemented\" na n.iso sem evidência vinculada ou com evidência fora do período | Listar evidências por controle no snapshot e checar data e conteúdo | NC menor por controle; NC maior se ≥3 no mesmo tema (8.1) |\n| 5 | Análise crítica incompleta | Ata da 9.3 sem alguma das entradas da 9.3.2 ou sem decisões (9.3.3) | Checar a ata item a item contra a lista da 9.3.2 | NC menor por entrada ausente; NC maior se não houver análise crítica registrada |\n| 6 | Auditoria interna sem independência | Auditor interno que implementou o que auditou; programa inexistente; escopo parcial | Conferir programa, relatório e quem executou (9.2.2) | NC maior se ausente ou sem imparcialidade; NC menor se escopo parcial |\n| 7 | Objetivos sem medição | Objetivos de 6.2 sem indicador, meta, prazo ou resultado medido | Procurar medições do período (9.1) para cada objetivo | NC menor; NC maior se nenhum objetivo for medido |\n| 8 | Treinamento sem reciclagem | Treinamento único na admissão, sem reciclagem nem avaliação de eficácia | Comparar datas de treinamento com a periodicidade definida (7.2, 7.3, A.6.3) | NC menor; OM se só faltar avaliação de eficácia |\n| 9 | Exclusão sem justificativa | Controle excluído na SoA sem motivo, ou motivo genérico (\"não se aplica\") | Ler a justificativa de cada exclusão da SoA (27001 e 27701) | NC menor por item; NC maior se ≥3 exclusões sem justificativa (6.1.3 d) |\n",
      "references/clausulas-27001.md": "# ISO/IEC 27001:2022 — cláusulas 4 a 10 (paráfrase)\n\nParáfrase para uso na pré-avaliação; não substitui o texto oficial. \"ID obrigatória\" = informação documentada que a própria cláusula exige manter ou reter.\n\n| Cláusula | Exige | Informação documentada obrigatória | Pergunta do auditor | Amostra S2 |\n|---|---|---|---|---|\n| 4.1 | Identificar questões internas e externas relevantes ao propósito e aos resultados do SGSI | Não explícita (usual: análise de contexto) | Quais questões internas e externas afetam o SGSI e onde isso foi considerado no risco? | Análise de contexto revisada no período; vínculo com a avaliação de riscos |\n| 4.2 | Identificar partes interessadas, seus requisitos e quais serão tratados pelo SGSI | Não explícita (usual: registro de partes interessadas e requisitos legais) | Quem são as partes interessadas e quais requisitos delas o SGSI trata? | Registro de requisitos legais/contratuais atualizado; evidência de monitoramento das mudanças |\n| 4.3 | Definir limites e aplicabilidade do SGSI, considerando 4.1, 4.2, interfaces e dependências | Sim: escopo | O escopo cobre as interfaces e dependências com terceiros e nuvem? | Escopo aprovado; ativos e processos do inventário batem com o escopo |\n| 4.4 | Estabelecer, implementar, manter e melhorar o SGSI e seus processos | Não explícita | Como os processos do SGSI interagem e quem os opera? | Mapa de processos; evidência de operação de cada processo |\n| 5.1 | Alta direção demonstra liderança e comprometimento (política, recursos, integração, comunicação, melhoria) | Não explícita | Como a direção demonstra comprometimento além de assinar a política? | Atas, decisões de recursos, participação na análise crítica |\n| 5.2 | Política de segurança da informação adequada ao propósito, com objetivos ou estrutura para eles e compromissos de atendimento e melhoria | Sim: política | A política está aprovada, comunicada e disponível às partes interessadas? | Política aprovada com data; evidência de comunicação e aceite |\n| 5.3 | Atribuir e comunicar responsabilidades e autoridades, incluindo quem reporta o desempenho do SGSI | Não explícita (usual: matriz de papéis) | Quem responde pela conformidade do SGSI e pelo reporte à direção? | Nomeações formais; matriz de papéis coerente com os aprovadores dos documentos |\n| 6.1.1 | Determinar riscos e oportunidades considerando 4.1 e 4.2; planejar ações e avaliar sua eficácia | Não explícita | Como riscos e oportunidades do SGSI (não só de SI) foram tratados? | Ações planejadas com responsável e verificação de eficácia |\n| 6.1.2 | Processo de avaliação de riscos com critérios de aceitação e de avaliação, resultados consistentes, identificação de donos, análise e avaliação | Sim: processo de avaliação de riscos | Os critérios de aceitação estão definidos e são aplicados de forma repetível? | Metodologia; registro de riscos com dono, probabilidade, impacto e nível |\n| 6.1.3 | Processo de tratamento: escolher opções, determinar controles, comparar com o Anexo A, produzir a SoA, plano de tratamento e aprovação dos donos do risco | Sim: SoA; processo de tratamento | Cada controle da SoA tem justificativa de inclusão/exclusão e estado de implementação? Os donos aprovaram o risco residual? | SoA versionada; plano de tratamento; aceite formal de risco residual |\n| 6.2 | Objetivos de SI mensuráveis, monitorados, comunicados, com plano (o quê, recursos, responsável, prazo, avaliação) | Sim: objetivos | Como cada objetivo é medido e qual o resultado do último período? | Medições dos objetivos no período |\n| 6.3 | Mudanças no SGSI feitas de forma planejada | Não explícita | Houve mudança no SGSI no período? Como foi planejada? | Registro de mudança do SGSI com análise de impacto |\n| 7.1 | Determinar e prover recursos necessários ao SGSI | Não explícita | Os recursos para operar o SGSI foram definidos e providos? | Orçamento, alocação de pessoas, ferramentas |\n| 7.2 | Determinar competência necessária, garantir por formação/experiência e avaliar eficácia das ações | Sim: evidência de competência | Como a competência de quem opera controles críticos é comprovada? | Registros de formação/certificação; matriz de competências |\n| 7.3 | Pessoas conscientes da política, de sua contribuição e das consequências do não atendimento | Não explícita | Como se verifica que as pessoas conhecem a política? | Registros de conscientização; entrevista por amostra |\n| 7.4 | Definir comunicação interna e externa (o quê, quando, com quem, como) | Não explícita (usual: plano de comunicação) | Qual comunicação de SI é feita e para quem? | Evidência de comunicações realizadas |\n| 7.5.1 | O SGSI inclui a informação documentada exigida pela norma e a que a organização julgar necessária | Sim (conjunto) | Onde está a lista da informação documentada do SGSI? | Lista mestra de documentos |\n| 7.5.2 | Ao criar/atualizar: identificação, formato e análise crítica/aprovação | Sim (controle de documentos) | Como se sabe qual versão está aprovada e por quem? | Documentos com versão, data e aprovador |\n| 7.5.3 | Controlar a informação documentada: disponibilidade, proteção, distribuição, retenção e descarte; incluir origem externa | Sim (controle de documentos) | Como são controlados acesso, retenção e documentos externos? | Controle de acesso ao repositório; tabela de retenção |\n| 8.1 | Planejar, implementar e controlar os processos, incluindo critérios, controle de mudanças e processos externalizados | Sim: evidência de que os processos foram executados como planejado | Como se prova que os processos rodaram como planejado? Como são controlados os processos terceirizados? | Registros de operação; controle de fornecedores |\n| 8.2 | Executar avaliações de risco em intervalos planejados e em mudanças significativas | Sim: resultados da avaliação de riscos | Quando foi a última avaliação de riscos e o que a disparou? | Avaliação datada no período |\n| 8.3 | Implementar o plano de tratamento de riscos | Sim: resultados do tratamento | As ações do plano de tratamento foram executadas? | Status das ações com evidência |\n| 9.1 | Definir o que monitorar e medir, métodos, quando, quem e quando analisar | Sim: evidência dos resultados | Quais indicadores existem e quem os analisa? | Resultados de medição do período e análise |\n| 9.2.1 | Conduzir auditorias internas em intervalos planejados para verificar atendimento e eficácia | Não explícita aqui (ver 9.2.2) | Houve auditoria interna cobrindo todo o escopo antes do Stage 2? | Relatório de auditoria interna |\n| 9.2.2 | Programa de auditoria com frequência, métodos, responsabilidades; critérios e escopo; auditores objetivos e imparciais; relato à gestão | Sim: programa e resultados | Como a imparcialidade do auditor interno foi assegurada? | Programa; relatórios; independência do auditor |\n| 9.3.1 | Alta direção analisa criticamente o SGSI em intervalos planejados | Não explícita aqui (ver 9.3.3) | Quando foi a última análise crítica e quem participou? | Ata da análise crítica |\n| 9.3.2 | Entradas: status de ações anteriores, mudanças de questões, necessidades das partes interessadas, desempenho (NC, monitoramento, auditoria, objetivos), retorno das partes, riscos, oportunidades de melhoria | Não explícita aqui (ver 9.3.3) | A ata cobre todas as entradas exigidas? | Ata com cada entrada tratada |\n| 9.3.3 | Saídas: decisões de melhoria e necessidades de mudança | Sim: resultados da análise crítica | Quais decisões saíram da análise e estão sendo executadas? | Decisões com responsável e prazo; acompanhamento |\n| 10.1 | Melhorar continuamente adequação, suficiência e eficácia do SGSI | Não explícita | Qual melhoria concreta ocorreu no período? | Registro de melhorias |\n| 10.2 | Reagir à NC, avaliar causa, implementar ação, verificar eficácia, atualizar o SGSI | Sim: natureza das NC, ações e resultados | Mostre uma NC tratada até a verificação de eficácia | Registros de CAPA com causa raiz e verificação |\n",
      "references/clausulas-27701.md": "# ISO/IEC 27701:2025 — extensões do PIMS às cláusulas 4 a 10 (paráfrase)\n\n> **Numeração a confirmar contra o texto oficial da 27701:2025.** A edição 2025 passou a ser norma de sistema de gestão independente; a correspondência abaixo segue a estrutura das cláusulas 4–10 e deve ser conferida antes de citar número em achado. Em caso de dúvida, cite `27701 <cláusula> (a confirmar)`.\n\n| Cláusula | Exige | Informação documentada obrigatória | Pergunta do auditor | Amostra S2 |\n|---|---|---|---|---|\n| 4.1 | Determinar o papel da organização no tratamento de dados pessoais: controlador, operador ou ambos (inclusive controlador conjunto) | Sim (usual: declaração de papéis no escopo/ROPA) | Para cada tratamento, qual é o papel da organização e onde isso está registrado? | ROPA com papel por tratamento; contratos coerentes com o papel |\n| 4.2 | Incluir entre as partes interessadas os titulares de dados, a autoridade de proteção de dados e demais envolvidos no tratamento; identificar requisitos legais de privacidade | Não explícita (usual: registro de requisitos legais de privacidade) | Os requisitos da LGPD e da regulamentação da autoridade estão mapeados? | Registro de requisitos legais atualizado |\n| 4.3 | Escopo do PIMS incluindo o tratamento de dados pessoais | Sim: escopo | O escopo do PIMS declara quais tratamentos e dados pessoais estão dentro? | Escopo aprovado coerente com o ROPA |\n| 4.4 | Estabelecer, implementar, manter e melhorar o PIMS | Não explícita | Como os processos de privacidade se integram aos do SGSI? | Processos de privacidade operando (direitos do titular, incidentes) |\n| 5.1–5.3 | Liderança, política e papéis incluindo privacidade (compromisso com requisitos de proteção de dados; responsável pela privacidade) | Sim: política de privacidade/proteção de dados | Quem responde pela privacidade e qual a relação com o encarregado? | Política aprovada; nomeação do encarregado publicada |\n| 6.1.2 | Avaliação de riscos incluindo riscos ao titular (não só à organização) | Sim: processo de avaliação de riscos | Os riscos aos direitos e liberdades dos titulares foram avaliados? | Riscos de privacidade com impacto no titular; RIPD/DPIA quando cabível |\n| 6.1.3 | Tratamento de riscos com controles de privacidade; SoA incluindo controles do anexo da 27701 | Sim: SoA com controles de privacidade | A SoA inclui os controles de privacidade com justificativa de exclusão? | SoA com Tabelas A.1/A.3 (e A.2 se aplicável) |\n| 6.2 | Objetivos de privacidade mensuráveis | Sim: objetivos | Como se mede o desempenho em privacidade? | Medições (prazo de resposta ao titular, incidentes) |\n| 7.2–7.4 | Competência, conscientização e comunicação incluindo privacidade | Sim: evidência de competência | Quem trata dados pessoais foi treinado em privacidade? | Registros de treinamento em privacidade |\n| 7.5 | Informação documentada do PIMS, incluindo registros de tratamento | Sim | Onde estão os registros de tratamento? | ROPA versionado |\n| 8.1–8.3 | Operação, avaliação e tratamento de riscos de privacidade, incluindo operadores externos | Sim: resultados | Como se controla o tratamento feito por operadores/suboperadores? | Contratos com cláusulas de proteção de dados; avaliações de fornecedor |\n| 9.1–9.3 | Monitoramento, auditoria interna e análise crítica cobrindo o PIMS | Sim: resultados | A auditoria interna e a análise crítica cobriram privacidade? | Relatório e ata com itens de privacidade |\n| 10.1–10.2 | Melhoria e ação corretiva incluindo incidentes de privacidade | Sim: NC e ações | Mostre uma NC de privacidade tratada | CAPA de privacidade com verificação de eficácia |\n",
      "scripts/check_achados.py": "\"\"\"Valida CSV de achados da pré-avaliação de prontidão. Uso:\n  python check_achados.py achados.csv [--fontes RAIZ IDS.txt] [--proibidos termo1,termo2]\n  python check_achados.py --selftest\n\n--proibidos: termos vedados só para ESTE cliente (ex.: nome de outro cliente que\nnão pode aparecer no entregável). Somam-se aos termos vedados em qualquer caso.\n\"\"\"\nimport csv, io, os, sys\n\nCAB = \"id;bloco;requisito;severidade;veredito_s1;veredito_s2;pergunta_auditor;constatacao;fonte;correcao;dono;export_pedido\".split(\";\")\nSEV = {\"NC maior\", \"NC menor\", \"OM\"}\nVER = {\"atende\", \"parcial\", \"nao_atende\", \"na\"}\nOBRIG = [\"id\", \"bloco\", \"requisito\", \"severidade\", \"veredito_s1\", \"veredito_s2\", \"constatacao\", \"fonte\", \"correcao\", \"dono\"]\n# Vedados sempre: a pré-avaliação não é auditoria, e \"100%\" promete o que a certificadora decide.\nPROIBIDO = [\"auditado\", \"100%\"]\n\n\ndef validar(texto, raiz=None, ids=None, proibidos=()):\n    erros, vistos = [], set()\n    linhas = list(csv.reader(io.StringIO(texto), delimiter=\";\"))\n    if not linhas or linhas[0] != CAB:\n        return [\"ERRO linha 1: cabeçalho diferente do padrão\"], 0\n    for n, lin in enumerate(linhas[1:], start=2):\n        if len(lin) != len(CAB):\n            erros.append(f\"ERRO linha {n}: {len(lin)} colunas, esperado {len(CAB)}\"); continue\n        r = dict(zip(CAB, lin))\n        for c in OBRIG:\n            if not r[c].strip():\n                erros.append(f\"ERRO linha {n}: campo vazio {c}\")\n        if r[\"id\"] in vistos:\n            erros.append(f\"ERRO linha {n}: id duplicado {r['id']}\")\n        vistos.add(r[\"id\"])\n        if r[\"severidade\"] not in SEV:\n            erros.append(f\"ERRO linha {n}: severidade inválida {r['severidade']!r}\")\n        for c in (\"veredito_s1\", \"veredito_s2\"):\n            if r[c] not in VER:\n                erros.append(f\"ERRO linha {n}: {c} inválido {r[c]!r}\")\n        baixo = \" \".join(lin).lower()\n        for p in PROIBIDO + [t.strip().lower() for t in proibidos if t.strip()]:\n            if p in baixo:\n                erros.append(f\"ERRO linha {n}: termo proibido {p!r}\")\n        if raiz is not None:\n            for f in [x.strip() for x in r[\"fonte\"].split(\"|\") if x.strip()]:\n                if not (os.path.exists(os.path.join(raiz, f)) or f in ids):\n                    erros.append(f\"ERRO linha {n}: fonte não encontrada {f!r}\")\n    return erros, len(linhas) - 1\n\n\ndef _selftest():\n    boa = \";\".join(CAB) + \"\\nB1-01;1;4.3;NC menor;parcial;nao_atende;?;x;ctrl-a51;y;CIO;\\n\"\n    assert validar(boa, \".\", {\"ctrl-a51\"}) == ([], 1)\n    assert \"cabeçalho\" in validar(\"a;b\\n\")[0][0]\n    ruim = \";\".join(CAB) + \"\\nB1-01;1;4.3;Grave;talvez;na;?;x;;y;CIO;\\n\"\n    e, _ = validar(ruim)\n    assert any(\"severidade\" in m for m in e) and any(\"veredito_s1\" in m for m in e) and any(\"fonte\" in m for m in e)\n    dup = boa + \"B1-01;1;4.3;OM;atende;atende;?;x;ctrl-a51;y;CIO;\\n\"\n    assert any(\"duplicado\" in m for m in validar(dup)[0])\n    assert any(\"fonte não encontrada\" in m for m in validar(boa, \".\", set())[0])\n    assert any(\"proibido\" in m for m in validar(boa.replace(\";x;\", \";foi auditado;\"))[0])\n    # Termo vedado por cliente: só vale quando informado.\n    citado = boa.replace(\";x;\", \";cita o cliente Fulano;\")\n    assert validar(citado)[0] == []\n    assert any(\"proibido\" in m for m in validar(citado, proibidos=[\"fulano\"])[0])\n    print(\"selftest OK\")\n\n\nif __name__ == \"__main__\":\n    if sys.argv[1:] == [\"--selftest\"]:\n        _selftest(); sys.exit(0)\n    arq = sys.argv[1]\n    raiz = ids = None\n    proibidos = ()\n    if \"--proibidos\" in sys.argv:\n        proibidos = sys.argv[sys.argv.index(\"--proibidos\") + 1].split(\",\")\n    if \"--fontes\" in sys.argv:\n        i = sys.argv.index(\"--fontes\")\n        raiz = sys.argv[i + 1]\n        with open(sys.argv[i + 2], encoding=\"utf-8\") as fh:\n            ids = {l.strip() for l in fh if l.strip()}\n    with open(arq, encoding=\"utf-8-sig\") as fh:\n        erros, n = validar(fh.read(), raiz, ids, proibidos)\n    for m in erros:\n        print(m)\n    print(f\"OK {n} achados\" if not erros else f\"{len(erros)} erro(s)\")\n    sys.exit(1 if erros else 0)\n",
    },
  },
};
